refentry.refsect1:
&reftitle.parameters;
events
A non-empty list of Io\Poll\Event cases. It combines the conditions to watch for, such as Io\Poll\Event::Read and Io\Poll\Event::Write, with the Io\Poll\Event::OneShot and Io\Poll\Event::EdgeTriggered modifiers.

  &reftitle.examples;

   Re-arming a one-shot watcher


<?php
use Io\Poll\Context;
use Io\Poll\Event;
use Time\Duration;

[$reader, $writer] = stream_socket_pair(STREAM_PF_UNIX, STREAM_SOCK_STREAM, STREAM_IPPROTO_IP);

$context = new Context();
$watcher = $context->add(new StreamPollHandle($reader), [Event::Read, Event::OneShot]);

fwrite($writer, 'ping');

var_dump(count($context->wait(Duration::fromMilliseconds(10))));

// The watcher has triggered once and stays silent, although the data was not read.
var_dump(count($context->wait(Duration::fromMilliseconds(10))));

// Setting the events again re-arms the watcher.
$watcher->modifyEvents([Event::Read, Event::OneShot]);
var_dump(count($context->wait(Duration::fromMilliseconds(10))));


   &example.outputs;


int(1)
int(0)
int(1)
